417:function pacificAtlantic(a){const rows=a.length,cols=a[0].length,out=[];for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){let p=false,t=false;const q=[[y,x]],seen=new Set([y*cols+x]);for(let i=0;i<q.length;i++){const [r,c]=q[i];p||=r===0||c===0;t||=r===rows-1||c===cols-1;for(const [nr,nc]of [[r-1,c],[r+1,c],[r,c-1],[r,c+1]])if(nr>=0&&nc>=0&&nr<rows&&nc<cols&&!seen.has(nr*cols+nc)&&a[nr][nc]<=a[r][c]){seen.add(nr*cols+nc);q.push([nr,nc]);}}if(p&&t)out.push([y,x]);}return out;}
